    'https://example.com/%E3%81%93%E3%82%93%E3%81%AB%E3%81%A1%E3%81%AF'
  )
})

it('c.redirect() percent-encodes CR and LF', () => {
  let res = c.redirect('/destination\r\nX-Injected: evil')
  expect(res.status).toBe(302)
  expect(res.headers.get('Location')).toBe('/destination%0DX-Injected: evil')

  res = c.redirect('/destination\rX-Injected: evil')
  expect(res.headers.get('Location')).toBe('/destination%0DX-Injected: evil')

  res = c.redirect('/destination\nX-Injected: evil')
  expect(res.headers.get('Location')).toBe('/destination%0AX-Injected: evil')
})

it('c.redirect() keeps percent-encoded CR and LF unchanged', () => {
  const res = c.redirect('/destination%0D%0AX-Injected: evil')
  expect(res.status).toBe(302)
  expect(res.headers.get('Location')).toBe('/destination%0D%0AX-Injected: evil')
})

